(() => {
 const root=document.querySelector('.nemo-about');if(!root)return;
 const motion=matchMedia('(prefers-reduced-motion: reduce)');
 const tabs=[...root.querySelectorAll('[role="tab"]')],panels=[...root.querySelectorAll('[role="tabpanel"]')];
 let tabAnimation;
 function selectTab(index,focus=false){tabAnimation?.cancel();tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1;panels[i].hidden=i!==index;});if(!motion.matches)tabAnimation=panels[index].animate([{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:420,easing:'cubic-bezier(.22,1,.36,1)'});if(focus)tabs[index].focus();}
 tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(index));tab.addEventListener('keydown',event=>{let target;if(event.key==='ArrowRight')target=(index+1)%tabs.length;if(event.key==='ArrowLeft')target=(index+tabs.length-1)%tabs.length;if(event.key==='Home')target=0;if(event.key==='End')target=tabs.length-1;if(target!==undefined){event.preventDefault();selectTab(target,true);}});});
 const disclosures=[...root.querySelectorAll('.estimate-demo details')];disclosures.forEach(detail=>detail.addEventListener('toggle',()=>{if(!detail.open)return;disclosures.forEach(other=>{if(other!==detail)other.open=false;});if(!motion.matches)detail.querySelector('p').animate([{opacity:0,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:320,easing:'ease-out'});}));
 const reveals=[...root.querySelectorAll('[data-reveal]')];reveals.forEach((node,i)=>node.style.setProperty('--reveal-delay',(i%3)*60+'ms'));let revealObserver;
 if('IntersectionObserver' in window){const links=[...root.querySelectorAll('.about-nav a')];const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)links.forEach(link=>{if(link.hash==='#'+entry.target.id)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});});},{rootMargin:'-25% 0px -55% 0px',threshold:0});links.forEach(link=>{const section=root.querySelector(link.hash);if(section)sectionObserver.observe(section);});revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)entry.target.classList.add('is-visible');else if(entry.boundingClientRect.top>=innerHeight||entry.boundingClientRect.bottom<=0)entry.target.classList.remove('is-visible');}),{threshold:[0,.12]});reveals.forEach(node=>revealObserver.observe(node));}
 const purpose=root.querySelector('.about-manifesto'),purposeContent=root.querySelector('.manifesto-content');let scheduled=false;const clamp=n=>Math.min(1,Math.max(0,n)),ease=n=>n*n*(3-2*n);
 function updatePurpose(){scheduled=false;if(motion.matches){root.classList.remove('motion-ready');document.body.classList.remove('about-immersive');return;}const rect=purpose.getBoundingClientRect(),header=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--nemo-header-offset'))||0;const progress=clamp((header-rect.top)/Math.max(1,rect.height-(innerHeight-header)));const enter=ease(clamp((progress+.025)/.2)),exit=ease(clamp((progress-.79)/.21));purposeContent.style.setProperty('--purpose-opacity',String((.22+.78*enter)*(1-.65*exit)));purposeContent.style.setProperty('--purpose-scale',String(.96+.04*enter));purposeContent.style.setProperty('--purpose-shift',(18*(1-enter)-22*exit)+'px');purposeContent.style.setProperty('--purpose-second',String(.25+.75*ease(clamp((progress-.055)/.2))));purposeContent.style.setProperty('--purpose-second-shift',(15*(1-ease(clamp((progress-.055)/.2))))+'px');document.body.classList.toggle('about-immersive',rect.top<=header+40&&rect.bottom>innerHeight*.55);}
 function schedulePurpose(){if(!scheduled){scheduled=true;requestAnimationFrame(updatePurpose);}}
 function configureMotion(){reveals.forEach(node=>node.classList.toggle('reveal-ready',!motion.matches&&!!revealObserver));root.classList.toggle('motion-ready',!motion.matches);schedulePurpose();}
 addEventListener('scroll',schedulePurpose,{passive:true});addEventListener('resize',schedulePurpose);addEventListener('nemo:header',schedulePurpose);motion.addEventListener('change',configureMotion);configureMotion();
})();
